const offscreen = new OffscreenCanvas(200, 200);
const ctx = offscreen.getContext('2d');
ctx.fillStyle = 'tomato';
ctx.fillRect(0, 0, 200, 200);

const bitmap = offscreen.transferToImageBitmap();
// bitmap 拿到了画布内容
// offscreen 画布此时已被清空（变为透明）

// 可以高效地画到可见 canvas 上
visibleCtx.drawImage(bitmap, 0, 0);
bitmap.close(); // 用完释放 GPU/内存资源

const offscreen = new OffscreenCanvas(400, 300);
const ctx = offscreen.getContext('2d');
ctx.fillStyle = 'steelblue';
ctx.fillRect(0, 0, 400, 300);
ctx.fillStyle = 'white';
ctx.font = '32px sans-serif';
ctx.fillText('Hello', 150, 160);

const blob = await offscreen.convertToBlob({
  type: 'image/png',    // 'image/png' | 'image/jpeg' | 'image/webp'
  quality: 0.92         // 仅对 jpeg/webp 有效，范围 0~1
});

// 用途1：下载
const url = URL.createObjectURL(blob);
const a = document.createElement('a');
a.href = url;
a.download = 'output.png';
a.click();

// 用途2：上传
fetch('/upload', { method: 'POST', body: blob });
